import { test } from "node:test";
import assert from "node:assert";
import { parseCsvLine } from "./csv";
test("plain", () => assert.deepStrictEqual(parseCsvLine("a,b,c"), ["a","b","c"]));
test("quoted", () => assert.deepStrictEqual(parseCsvLine('a,"b,c",d'), ["a","b,c","d"]));
test("escaped", () => assert.deepStrictEqual(parseCsvLine('"a""b"'), ['a"b']));
test("trailing", () => assert.deepStrictEqual(parseCsvLine("a,"), ["a",""]));
